import{_ as t,C as r,o as e,c as h,j as i,E as s,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const U=JSON.parse(`{"title":"16-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (3-qism): Jonli o'yin HUD'i (Health bar, tangalar, mini-xarita)","description":"","frontmatter":{"title":"16-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (3-qism): Jonli o'yin HUD'i (Health bar, tangalar, mini-xarita)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":6,"link":"/mentor/9-sinf-game/hafta-06/"},"g":16,"title":"UI dizayn: tugmalar, menyular, HUD (3-qism): Jonli o'yin HUD'i (Health bar, tangalar, mini-xarita)","lead":"O'yin davomida sog'liq, tangalar va xarita doim ko'z oldimizda. Bugun shu jonli HUD'ni Photoshop'da o'zimiz chizamiz.","slide":"/slaydlar/9-sinf-game/hafta-06/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-06/dars-1-test.html","student_link":"/9-sinf-game/hafta-06/dars-1","tabs":[{"g":16,"link":"/mentor/9-sinf-game/hafta-06/dars-1","current":true},{"g":17,"link":"/mentor/9-sinf-game/hafta-06/dars-2","current":false},{"g":18,"link":"/mentor/9-sinf-game/hafta-06/dars-3","current":false}],"prev":null,"next":{"g":17,"title":"O'yin interfeysini prototiplash (1-qism): Wireframe, Mockup va Prototype bosqichlari","link":"/mentor/9-sinf-game/hafta-06/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-06/dars-1.md","filePath":"mentor/9-sinf-game/hafta-06/dars-1.md"}`),g={name:"mentor/9-sinf-game/hafta-06/dars-1.md"},p={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},m={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},b={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},c={class:"blk"},q={id:"tezkor-nazorat-savollari",tabindex:"-1"},y={class:"blk"},v={id:"uyga-vazifa",tabindex:"-1"};function f(x,a,z,_,H,T){const n=r("Icon");return e(),h("div",null,[i("div",p,[i("h2",d,[s(n,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga HUD ning vazifasini va tarkibini (sog&#39;liq paneli, tangalar/ballar, mini-xarita, vaqt, inventar), HUD ga qo&#39;yiladigan talablarni (aniqlik, joylashuv, minimalizm, janrga moslik, vizual uslub) o&#39;rgatish hamda Photoshop&#39;da health bar, tanga hisoblagichi va mini-xaritadan iborat jonli o&#39;yin HUD maketini chizishni mashq qildirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar hUD ning 5 ta talabini va 4 ta asosiy elementini aytadi; health bar&#39;ni 3 qatlamda (fon, to&#39;ldirish, ramka) chizadi va to&#39;ldirish uzunligini foizdan hisoblaydi; tanga hisoblagichini ikonka va matndan yig&#39;adi; mini-xaritani Ellipse Tool bilan chizib, qahramon va dushman belgilarini joylashtiradi; hUD elementlarini guruhlaydi va shaffof fonli PNG qilib eksport qiladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>14–15-dars: tugma holatlari, menyular: 10 daqiqa</li><li>HUD: tarkibi va talablari: 10 daqiqa</li><li>Health bar va tanga hisoblagichi: 20 daqiqa</li><li>Mini-xarita, guruhlash, eksport: 15 daqiqa</li><li>Amaliyot: to&#39;liq HUD maketi: 25 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «UI dizayn: tugmalar, menyular, HUD» moduli («HUD tushunchasi, unga qo&#39;yilgan talablar va o&#39;yinlarda vazifasi»); o&#39;quv qo&#39;llanma — 2.4-bo&#39;lim («2.6-jadval. HUD tarkibi», HUD talablari, Photoshop&#39;da UI yaratish bosqichlari: 1920×1080, Transparent fon, har element alohida layerda); uslubiy ko&#39;rsatma — 1.4–1.5-mashg&#39;ulotlar (Rectangle/Ellipse Tool, Blending Options, Ctrl+G, tanga ikonkasi, Export). Piksel o&#39;lchamlari va rang chegaralari (yashil/sariq/qizil) — namunaviy tavsiya, mentor o&#39;zgartirishi mumkin.</p></blockquote><hr>",3))]),i("div",m,[i("h2",u,[s(n,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o(`<h3 id="_1-jonli-o-yin-hud-i-tarkibi-va-talablari" tabindex="-1">1. Jonli o&#39;yin HUD&#39;i: tarkibi va talablari <a class="header-anchor" href="#_1-jonli-o-yin-hud-i-tarkibi-va-talablari" aria-label="Permalink to &quot;1. Jonli o&#39;yin HUD&#39;i: tarkibi va talablari&quot;">​</a></h3><p><strong>HUD</strong> (Head-Up Display) — o&#39;yin davomida o&#39;yinchiga zarur ma&#39;lumotni doimiy ko&#39;rsatadigan «ekran usti interfeysi». Qo&#39;llanmadagi 2.6-jadvalga ko&#39;ra HUD tarkibi: <strong>sog&#39;liq paneli</strong> (HP — qahramonning sog&#39;lig&#39;i), <strong>energiya/mana</strong>, <strong>xarita/minimap</strong> (joylashuv va yo&#39;nalish), <strong>ball, statistika, resurslar</strong> (masalan, tangalar), <strong>qurol yoki inventar</strong>, <strong>vaqt yoki topshiriqlar</strong>. Talablar: 1) <strong>aniqlik va o&#39;qilishi</strong> — kontrast, tushunarli shrift va belgi; 2) <strong>joylashuv</strong> — odatda ekran burchaklarida, o&#39;yinchi ko&#39;rish maydoniga xalaqit bermaydi; 3) <strong>minimalizm</strong> — ortiqcha element yo&#39;q; 4) <strong>janrga moslik</strong> — shooter&#39;da minimal va tezkor, RPG&#39;da batafsil; 5) <strong>vizual uslub</strong> — ranglar, ikonkalar va ramkalar o&#39;yin uslubiga mos. Bugun «Robo-changyutkich» o&#39;yinining HUD&#39;ini chizamiz: chap yuqorida health bar, o&#39;ng yuqorida tangalar, o&#39;ng pastda mini-xarita.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+--------------------------------------------------+</span></span>
<span class="line"><span>| [HP ########--] 80/100               COIN x 12   |</span></span>
<span class="line"><span>|                                                  |</span></span>
<span class="line"><span>|                                                  |</span></span>
<span class="line"><span>|                  O&#39;yin sahnasi                   |</span></span>
<span class="line"><span>|                                                  |</span></span>
<span class="line"><span>|                                      +--------+  |</span></span>
<span class="line"><span>|                                      | mini-  |  |</span></span>
<span class="line"><span>|                                      | xarita |  |</span></span>
<span class="line"><span>|                                      +--------+  |</span></span>
<span class="line"><span>+--------------------------------------------------+</span></span></code></pre></div><blockquote><p>Professional maslahat: Markaz bo&#39;sh qoladi — o&#39;yinchi sahnani ko&#39;rishi kerak. HUD elementlari burchaklarga yig&#39;iladi.</p></blockquote><h3 id="_2-health-bar-va-tanga-hisoblagichini-chizish" tabindex="-1">2. Health bar va tanga hisoblagichini chizish <a class="header-anchor" href="#_2-health-bar-va-tanga-hisoblagichini-chizish" aria-label="Permalink to &quot;2. Health bar va tanga hisoblagichini chizish&quot;">​</a></h3><p>Yangi hujjat: <strong>File → New</strong>, 1920×1080 px, RGB, <strong>Background Contents → Transparent</strong> — shunda HUD elementlari shaffof fonli bo&#39;ladi (qo&#39;llanma). Har element <strong>alohida layerda</strong> bo&#39;ladi. <strong>Health bar uch qatlamdan</strong> iborat: 1) <strong>Fon</strong> — to&#39;q kulrang Rounded Rectangle (masalan, 400×40 px); 2) <strong>To&#39;ldirish</strong> — shu o&#39;lchamdagi, rangli (qizil yoki yashil) shakl; 3) <strong>Ramka</strong> — Blending Options → Stroke yoki Properties panelidagi Stroke. To&#39;ldirish uzunligi sog&#39;liq foiziga bog&#39;liq: <strong>uzunlik = bar kengligi × HP / maksimal HP</strong>. 400 px bar, HP 80/100 bo&#39;lsa: 400 × 0,8 = <strong>320 px</strong>; 25/100 bo&#39;lsa — 100 px. Bar yoniga yurak ikonkasi va «80/100» matni qo&#39;yiladi (Text Tool). Tanga hisoblagichi: tanga ikonkasi (uslubiy ko&#39;rsatmadagi kabi Move Tool bilan kerakli joyga) + «x 12» matni; ikkalasi Ctrl+G bilan bitta guruhga yig&#39;ilib, «Tangalar» deb nomlanadi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Bar kengligi: 400 px, maksimal HP: 100</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HP 100  -&gt;  400 * 100 / 100 = 400 px</span></span>
<span class="line"><span>HP  80  -&gt;  400 *  80 / 100 = 320 px</span></span>
<span class="line"><span>HP  50  -&gt;  400 *  50 / 100 = 200 px</span></span>
<span class="line"><span>HP  25  -&gt;  400 *  25 / 100 = 100 px</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rang: 50% dan ko&#39;p - yashil</span></span>
<span class="line"><span>      25-50%      - sariq</span></span>
<span class="line"><span>      25% dan kam - qizil</span></span></code></pre></div><blockquote><p>Professional maslahat: Rang almashishi — namunaviy tavsiya: o&#39;yinchi sog&#39;lig&#39;i kamayganini rangdan darrov tushunadi.</p></blockquote><h3 id="_3-mini-xarita-guruhlash-va-eksport" tabindex="-1">3. Mini-xarita, guruhlash va eksport <a class="header-anchor" href="#_3-mini-xarita-guruhlash-va-eksport" aria-label="Permalink to &quot;3. Mini-xarita, guruhlash va eksport&quot;">​</a></h3><p><strong>Mini-xarita</strong> qahramonning atrofini ko&#39;rsatadi, joylashuv va yo&#39;nalishni bildiradi (qo&#39;llanma: dushmanlar va joylarning o&#39;rnini ko&#39;rsatadi). Photoshop&#39;da: <strong>Ellipse Tool (U)</strong> tanlanadi, <strong>Shift</strong> bosib turib sichqoncha tortiladi — mukammal doira hosil bo&#39;ladi (uslubiy ko&#39;rsatma); doira ichiga xarita fonini (to&#39;q rang yoki xona tasviri) qo&#39;ying, markazga qahramon belgisini (kichik och doira), atrofga dushman belgilarini (qizil nuqtalar) joylashtiring, ramka uchun Stroke bering. Joyi — o&#39;ng pastki burchak. Keyin HUD qatlamlarini tartiblang: Shift bilan tanlab, <strong>Ctrl + G</strong> bilan guruhlang va nomlang: «HP», «Tangalar», «Mini-xarita», ularni esa umumiy «HUD» guruhiga soling. Eksport: <strong>File → Export → Export As…</strong> — <strong>PNG</strong> (shaffoflik saqlanadi). Qo&#39;llanmaga ko&#39;ra shaffof fonli HUD o&#39;yin dvigateliga (masalan, Unity) Sprite sifatida import qilinadi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>HUD</span></span>
<span class="line"><span>  HP</span></span>
<span class="line"><span>    Ikonka (yurak)</span></span>
<span class="line"><span>    Matn 80/100</span></span>
<span class="line"><span>    Bar ramka</span></span>
<span class="line"><span>    Bar to&#39;ldirish</span></span>
<span class="line"><span>    Bar fon</span></span>
<span class="line"><span>  Tangalar</span></span>
<span class="line"><span>    Matn x 12</span></span>
<span class="line"><span>    Ikonka (tanga)</span></span>
<span class="line"><span>  Mini-xarita</span></span>
<span class="line"><span>    Qahramon belgisi</span></span>
<span class="line"><span>    Dushman belgilari</span></span>
<span class="line"><span>    Xarita fon</span></span></code></pre></div><blockquote><p>Professional maslahat: Yuqori qatlam — ustida ko&#39;rinadi: ramka to&#39;ldirishdan, matn esa fondan tepada turishi kerak.</p></blockquote><hr>`,13))]),i("div",b,[i("h2",k,[s(n,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-hud-elementlari-oson" tabindex="-1">1-topshiriq. HUD elementlari (oson) <a class="header-anchor" href="#_1-topshiriq-hud-elementlari-oson" aria-label="Permalink to &quot;1-topshiriq. HUD elementlari (oson)&quot;">​</a></h3><p>HUD ning kamida 4 ta elementini sanang va har birining vazifasini yozing.</p><p><strong>Bajarish tartibi:</strong> Sog&#39;liq paneli — qahramon sog&#39;lig&#39;ini ko&#39;rsatadi; tanga/ball hisoblagichi — yig&#39;ilgan resursni; mini-xarita — joylashuv va yo&#39;nalishni; vaqt/inventar — topshiriq vaqti yoki qurol holatini.</p><h3 id="_2-topshiriq-burchaklar-oson" tabindex="-1">2-topshiriq. Burchaklar (oson) <a class="header-anchor" href="#_2-topshiriq-burchaklar-oson" aria-label="Permalink to &quot;2-topshiriq. Burchaklar (oson)&quot;">​</a></h3><p>Health bar, tangalar va mini-xaritani ekranning qaysi burchaklariga qo&#39;yasiz?</p><p><strong>Bajarish tartibi:</strong> Health bar — chap yuqori; tangalar — o&#39;ng yuqori; mini-xarita — o&#39;ng pastki. Markaz bo&#39;sh qoladi.</p><h3 id="_3-topshiriq-bar-uzunligi-o-rta" tabindex="-1">3-topshiriq. Bar uzunligi (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-bar-uzunligi-o-rta" aria-label="Permalink to &quot;3-topshiriq. Bar uzunligi (o&#39;rta)&quot;">​</a></h3><p>Bar kengligi 400 px. HP 60/100 va 35/100 bo&#39;lsa, to&#39;ldirish uzunligi qancha?</p><p><strong>Bajarish tartibi:</strong> 400 × 60 / 100 = 240 px; 400 × 35 / 100 = 140 px.</p><h3 id="_4-topshiriq-health-bar-chizish-o-rta" tabindex="-1">4-topshiriq. Health bar chizish (o&#39;rta) <a class="header-anchor" href="#_4-topshiriq-health-bar-chizish-o-rta" aria-label="Permalink to &quot;4-topshiriq. Health bar chizish (o&#39;rta)&quot;">​</a></h3><p>Photoshop&#39;da 400×40 px health bar&#39;ni 3 qatlamda chizing.</p><p><strong>Bajarish tartibi:</strong></p><ol><li>Rounded Rectangle 400×40 px, to&#39;q kulrang — «Bar fon». 2) Shu o&#39;lchamdagi rangli shakl — «Bar to&#39;ldirish». 3) To&#39;ldirish ustida Stroke qatlami yoki Blending Options → Stroke — «Bar ramka». Qatlamlar fon → to&#39;ldirish → ramka tartibida joylashadi.</li></ol><h3 id="_5-topshiriq-tanga-hisoblagichi-qiyin" tabindex="-1">5-topshiriq. Tanga hisoblagichi (qiyin) <a class="header-anchor" href="#_5-topshiriq-tanga-hisoblagichi-qiyin" aria-label="Permalink to &quot;5-topshiriq. Tanga hisoblagichi (qiyin)&quot;">​</a></h3><p>Tanga ikonkasi va «x 12» matnidan hisoblagich yig&#39;ing, guruhlang va nom bering.</p><p><strong>Bajarish tartibi:</strong> Move Tool bilan tanga ikonkasini o&#39;ng yuqoriga qo&#39;ying; Text Tool bilan «x 12» yozing (o&#39;lcham va rangni Properties panelida sozlang); ikkala qatlamni Shift bilan tanlab Ctrl + G bosing va guruhni «Tangalar» deb nomlang.</p><h3 id="_6-topshiriq-to-liq-hud-bonus" tabindex="-1">6-topshiriq. To&#39;liq HUD (bonus) <a class="header-anchor" href="#_6-topshiriq-to-liq-hud-bonus" aria-label="Permalink to &quot;6-topshiriq. To&#39;liq HUD (bonus)&quot;">​</a></h3><p>Uchala elementdan iborat HUD&#39;ni chizing, «HUD» guruhiga soling va shaffof PNG qilib eksport qiling.</p><p><strong>Bajarish tartibi:</strong> Ellipse Tool + Shift bilan mini-xarita doirasini chizing, qahramon (och) va dushman (qizil) belgilarini qo&#39;ying; barcha guruhlarni «HUD» ga soling; File → Export → Export As… → PNG, Transparency yoqilgan.</p><hr>',20))]),i("div",c,[i("h2",q,[s(n,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>HUD nima? <ul><li><em>Javob:</em> O&#39;yin davomida doim ko&#39;rinadigan ma&#39;lumot — ekran usti interfeysi.</li></ul></li><li>HUD ning 3 ta elementini ayting. <ul><li><em>Javob:</em> Masalan: sog&#39;liq paneli, mini-xarita, tanga/ball hisoblagichi.</li></ul></li><li>HUD talablaridan 3 tasi? <ul><li><em>Javob:</em> Aniqlik, burchaklarda joylashuv, minimalizm.</li></ul></li><li>Health bar nechta qatlamdan iborat? <ul><li><em>Javob:</em> Uchta: fon, to&#39;ldirish, ramka.</li></ul></li><li>Shaffof fonli HUD qaysi formatda eksport qilinadi? <ul><li><em>Javob:</em> PNG.</li></ul></li></ol><hr>",2))]),i("div",y,[i("h2",v,[s(n,{name:"house"}),a[12]||(a[12]=l(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"1920×1080 px, Transparent fonli hujjatda health bar'ni (fon, to'ldirish, ramka) chizing; HP 70/100 holatiga to'g'ri uzunlik hisoblang."),i("li",null,"Tanga hisoblagichini (ikonka + «x 12») chizing va «Tangalar» guruhiga soling."),i("li",null,"Mini-xaritani Ellipse Tool bilan chizing; qahramon va 2 ta dushman belgisini qo'ying."),i("li",null,"Barcha qatlamlarni «HUD» guruhiga yig'ib, shaffof PNG qilib eksport qiling."),i("li",null,"HUD joylashuvi haqida 3 gaplik izoh yozing: nima uchun elementlar aynan shu joylarda?")],-1))])])}const D=t(g,[["render",f]]);export{U as __pageData,D as default};
